def admitted_blocks(widgets):
    """Decode the Textual mount boundary once before category consumers."""
    for widget in widgets:
        if not isinstance(widget, ConversationBlock):
            raise TypeError("Conversation contents require nominal blocks")
    return widgets

class CategorizedMount:
    """Apply the owning conversation category selection at widget admission."""

    def mount(self, *widgets, **kwargs):
        from toad.widgets.message_filter import apply_block_filter, block_category, keep_live_block

        selected = self.query_ancestor(Conversation).visible_categories if self.is_attached else all_categories()
        for widget in admitted_blocks(widgets):
            classes = {"-unrouted": not keep_live_block(widget)}
            if category := block_category(widget):
                classes[f"-message-{category.declared_name}"] = True
            # Registration owns the first CSS match for detached blocks. For
            # attached blocks, Textual applies this class change as one batch.
            widget.update_classes(classes, update=widget.is_attached)
            apply_block_filter(widget, selected)
        return super().mount(*widgets, **kwargs)

def block_category(widget) -> type[MessageCategory] | None:
    """Ask the native block; uncategorized controls belong to Other."""
    return (
        widget.message_category
        if isinstance(widget, CategorizedBlock)
        else OtherCategory
    )

def keep_live_block(widget) -> bool:
    category = block_category(widget)
    return (
        category is None
        or category.keep_native_block()
        or widget.has_class("-error")
        or widget.has_class("-error-log-link")
    )
